import {
    Group,
    Mesh,
    MeshPhysicalMaterial,
    SphereGeometry,
    CylinderGeometry,
    PlaneGeometry,
    Color,
    Vector3,
    Texture,
    RepeatWrapping,
    DoubleSide,
    NodeMaterial,
    PositionNode,
    NormalNode,
    UVNode,
    TextureNode,
    MathNode,
    OperatorNode,
    FloatNode,
    Vector2Node,
    ColorNode,
    MixNode,
    PowNode,
    SinNode,
    CosNode,
    AddNode,
    SubNode,
    LengthNode,
    TransformNode,
    Node
} from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import { createMSDFMaterial } from '@/text';

export default function createNode(config, ctx) {
    const root = new Group();
    const { position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1] } = config;
    root.position.set(...position);
    root.rotation.set(...rotation);
    root.scale.set(...scale);

    // Load GLB (synchronous via cached loader)
    const glb = ctx.glbLoader(config.assets?.meshUrl);
    // Assume the GLB contains the primary gear mesh as its first child
    const primaryGear = glb.clone();
    primaryGear.scale.setScalar(1.6 / (primaryGear.geometry?.boundingSphere?.radius || 1));
    // Apply machined steel material overrides
    primaryGear.traverse((obj) => {
        if (obj.isMesh) {
            const mat = new MeshPhysicalMaterial({
                metalness: 0.55,
                roughness: 0.5,
                clearcoat: 0.2,
                clearcoatRoughness: 0.3,
                anisotropy: 0.7,
                anisotropyRotation: 0
            });
            obj.material = mat;
        }
    });
    root.add(primaryGear);

    // Secondary gear instance
    const secondaryGear = primaryGear.clone();
    const secondaryScale = 0.9 / 1.6; // target diameter 0.9 unit
    secondaryGear.scale.setScalar(secondaryScale);
    secondaryGear.position.set(1.15, 0.35, -0.1);
    root.add(secondaryGear);

    // Jewel pivot sphere
    const jewelGeom = new SphereGeometry(0.12, 32, 32);
    const jewelMat = new MeshPhysicalMaterial({
        color: new Color('#ff2a38'),
        transmission: 0.6,
        ior: 1.76,
        emissive: new Color('#ff2a38'),
        emissiveIntensity: 1.8,
        metalness: 0,
        roughness: 0.2,
        clearcoat: 0
    });
    const jewel = new Mesh(jewelGeom, jewelMat);
    jewel.position.set(0, 0, 0);
    root.add(jewel);

    // Arbor shafts (ink cylinders)
    const shaftGeom = new CylinderGeometry(0.05, 0.05, 0.8, 16);
    const shaftMat = new MeshPhysicalMaterial({ color: new Color('#16161d') });
    const shaftA = new Mesh(shaftGeom, shaftMat);
    const shaftB = shaftA.clone();
    shaftA.rotation.x = Math.PI / 2;
    shaftB.rotation.x = Math.PI / 2;
    shaftA.position.set(0, 0, 0);
    shaftB.position.set(0, 0, 0);
    root.add(shaftA, shaftB);

    // Contact shadow ellipse
    const shadowGeom = new PlaneGeometry(2.6, 1.2);
    const shadowMat = new MeshPhysicalMaterial({
        color: new Color('#000000'),
        transparent: true,
        opacity: 0.5,
        depthWrite: false,
        side: DoubleSide
    });
    const shadow = new Mesh(shadowGeom, shadowMat);
    shadow.rotation.x = -Math.PI / 2;
    shadow.position.set(0, -1.2, 0);
    root.add(shadow);

    // Backdrop plane with radial gradient (using TSL nodes)
    const backdropGeom = new PlaneGeometry(7, 6);
    const gradientStops = config.visual?.Colors?.gradientStops || [
        { at: 0, hex: '#0b0b10' },
        { at: 0.65, hex: '#101017' },
        { at: 1, hex: '#16161d' }
    ];
    const gradientNode = (() => {
        const uv = new UVNode();
        const centeredUV = new SubNode(uv, new Vector2Node(0.5, 0.5));
        const dist = new LengthNode(centeredUV);
        const stops = gradientStops.map(stop => ({
            position: new FloatNode(stop.at),
            color: new ColorNode(new Color(stop.hex))
        }));
        // Linear interpolation across stops
        let col = stops[0].color;
        for (let i = 1; i < stops.length; i++) {
            const t = new OperatorNode(
                new SubNode(dist, stops[i - 1].position),
                new SubNode(stops[i].position, stops[i - 1].position),
                OperatorNode.DIVIDE
            );
            const clamped = new MathNode(t, MathNode.CLAMP);
            col = new MixNode(col, stops[i].color, clamped);
        }
        return col;
    })();
    const backdropMat = new NodeMaterial();
    backdropMat.color = gradientNode;
    backdropMat.transparent = true;
    backdropMat.depthWrite = false;
    backdropMat.side = DoubleSide;
    const backdrop = new Mesh(backdropGeom, backdropMat);
    backdrop.position.set(0, 0, -3);
    root.add(backdrop);

    // Fog (scene level) – assume ctx.scene is available
    if (ctx.scene) {
        ctx.scene.fog = new ctx.Fog('#0b0b10', 5, 11);
    }

    // Text meshes using MSDF material
    const createText = (txt, style) => {
        const plane = new PlaneGeometry(style.width, style.height);
        const msdfMat = createMSDFMaterial({
            atlas: ctx.fontAtlas,
            text: txt,
            color: new Color(style.color),
            opacity: 1,
            size: style.fontSize,
            letterSpacing: style.letterSpacing,
            lineHeight: style.lineHeight
        });
        const mesh = new Mesh(plane, msdfMat);
        mesh.position.set(style.x, style.y, style.z);
        return mesh;
    };
    // Headline
    const headlineStyle = {
        fontSize: 68,
        color: '#ffffff',
        letterSpacing: -0.005,
        lineHeight: 1.1,
        width: 4, // approximate
        height: 0.62,
        x: 0,
        y: -1.7,
        z: 0.01
    };
    const headline = createText('The going train', headlineStyle);
    root.add(headline);
    // Caption
    const captionStyle = {
        fontSize: 18,
        color: '#ffffff',
        letterSpacing: 0.08,
        lineHeight: 1.4,
        width: 3,
        height: 0.18,
        x: 0,
        y: -2.1,
        z: 0.01
    };
    const caption = createText('34 COMPONENTS / HAND-FINISHED', captionStyle);
    root.add(caption);

    // Gear rotation animation
    const primarySpeed = 0.08; // rad/s
    const secondarySpeed = -0.142; // rad/s
    const primaryTL = gsap.timeline({ repeat: -1, paused: false });
    primaryTL.to(primaryGear.rotation, {
        y: `+=${Math.PI * 2}`,
        duration: (Math.PI * 2) / primarySpeed,
        ease: 'none'
    }, 0);
    const secondaryTL = gsap.timeline({ repeat: -1, paused: false });
    secondaryTL.to(secondaryGear.rotation, {
        y: `+=${Math.PI * 2}`,
        duration: (Math.PI * 2) / Math.abs(secondarySpeed),
        ease: 'none',
        modifiers: {
            y: (value) => parseFloat(value) * Math.sign(secondarySpeed)
        }
    }, 0);

    // Apply cinematic primitives from config
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const primitive of config.cinematicPrimitives) {
            const fn = ctx.primitives?.[primitive.name];
            if (typeof fn === 'function') {
                fn(root, primitive.params);
            }
        }
    }

    // Event handlers placeholder
    root.userData.handlers = {};

    // Cleanup
    root.userData.cleanup = () => {
        primaryTL.kill();
        secondaryTL.kill();
        root.traverse((obj) => {
            if (obj.isMesh) {
                if (obj.geometry) obj.geometry.dispose();
                if (obj.material) {
                    if (Array.isArray(obj.material)) {
                        obj.material.forEach((m) => m.dispose());
                    } else {
                        obj.material.dispose();
                    }
                }
            }
        });
    };

    return root;
}
